cat > /home/vagrant/work/free5gc/config/add-subscriber.js <<'EOF'
// Provision imsi-208930000000001 (PLMN 208/93, SST 1 / SD 010203, DNN internet),
// mirroring the document layout used by docker/free5gc/free5gc-dbpython/add_subscribers.py.
const ueId = "imsi-208930000000001";
const db = db.getSiblingDB("free5gc");
const plmn = "20893";
const snssai = { sst: Double(1), sd: "010203" };
const dnnCfg = {
  "5gQosProfile": { "5qi": Double(9), arp: { preemptCap: "", preemptVuln: "", priorityLevel: Double(8) }, priorityLevel: Double(8) },
  pduSessionTypes: { allowedSessionTypes: ["IPV4"], defaultSessionType: "IPV4" },
  sessionAmbr: { downlink: "100 Mbps", uplink: "200 Mbps" },
  sscModes: { allowedSscModes: ["SSC_MODE_2", "SSC_MODE_3"], defaultSscMode: "SSC_MODE_1" }
};
const docs = {
  "subscriptionData.provisionedData.smfSelectionSubscriptionData": [{
    servingPlmnId: plmn, ueId,
    subscribedSnssaiInfos: { "01010203": { dnnInfos: [{ dnn: "internet" }] } } }],
  "subscriptionData.provisionedData.smData": [{
    dnnConfigurations: { internet: dnnCfg }, servingPlmnId: plmn, singleNssai: snssai, ueId }],
  "policyData.ues.smData": [{
    smPolicySnssaiData: { "01010203": { smPolicyDnnData: { internet: { dnn: "internet" } }, snssai: snssai } }, ueId }],
  "policyData.ues.amData": [{ subscCats: ["free5gc"], ueId }],
  "subscriptionData.provisionedData.amData": [{
    gpsis: ["msisdn-0900000000"], nssai: { defaultSingleNssais: [snssai] }, servingPlmnId: plmn,
    subscribedUeAmbr: { downlink: "2 Gbps", uplink: "1 Gbps" }, ueId }],
  "subscriptionData.authenticationData.authenticationSubscription": [{
    authenticationManagementField: "8000", authenticationMethod: "5G_AKA",
    milenage: { op: { encryptionAlgorithm: Double(0), encryptionKey: Double(0), opValue: "" } },
    opc: { encryptionAlgorithm: Double(0), encryptionKey: Double(0), opcValue: "8e27b6af0e692e750f32667a3b14605d" },
    permanentKey: { encryptionAlgorithm: Double(0), encryptionKey: Double(0), permanentKeyValue: "8baf473f2f8fd09487cccbd7097c6862" },
    sequenceNumber: "16f3b3f70fc2", ueId }]
};
for (const [col, arr] of Object.entries(docs)) {
  db.getCollection(col).deleteMany({ ueId });
  const r = db.getCollection(col).insertMany(arr);
  print(col + ": inserted " + Object.keys(r.insertedIds).length);
}
EOF
cd /home/vagrant/work/free5gc/config && kubectl -n free5gc exec -i mongodb-0 -- sh -c 'command -v mongosh || command -v mongo' ; kubectl -n free5gc exec -i mongodb-0 -- sh -c 'if command -v mongosh >/dev/null; then mongosh --quiet; else mongo --quiet; fi' < add-subscriber.js; echo "exit=$?"

